import java.util.concurrent.locks.{Lock, ReentrantLock}

final class FileCache(strategy: Lock = new ReentrantLock) {
  def find(path: String): Option[String] = {
    strategy.lock()
    try findLocked(path)          // assumes the lock is held
    finally strategy.unlock()     // Scoped Locking emulated (no RAII on the JVM)
  }
}
